  select id, 'L01', 'lesson', 'l01-the-psychology-of-speaking-in-a-second-language', 'The Psychology of Speaking in a Second Language', 'Why fluent clinicians feel less competent in English, and how audiences actually judge non-native speakers.', 55, 1, 1, true, 'not_recorded', 'ready', 'speaking-mentor' from public.modules where number = 1
  on conflict (code) do update set module_id = excluded.module_id, kind = excluded.kind, slug = excluded.slug, title = excluded.title, summary = excluded.summary, duration_minutes = excluded.duration_minutes, week = excluded.week, position = excluded.position, is_preview = excluded.is_preview, video_status = excluded.video_status, content_status = excluded.content_status, ai_teacher = excluded.ai_teacher;
insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"Many doctors who read, write and think in English every day still feel less competent when they have to speak it in front of an audience. This lesson explains why that happens, what international audiences actually notice, and why your credibility rests far more on clarity and structure than on a native accent.","objectives":["Explain why speaking in a second language increases self-monitoring and anxiety","Distinguish between what speakers worry about and what audiences actually evaluate","Identify your own most common speaking triggers"],"sections":[{"heading":"The double task of second-language speaking","paragraphs":["When you present in your first language, most of your attention goes to the audience and the message. In a second language, part of that attention is diverted to monitoring grammar, vocabulary and pronunciation in real time. Researchers often describe this as an increased cognitive load: the same talk simply costs more mental effort.","The consequence is predictable. Under pressure, the extra monitoring competes with memory and fluency, so speakers lose words they know perfectly well, speed up to finish sentences before they lose them, or retreat to reading their slides. None of this reflects a lack of knowledge; it reflects divided attention."]},{"heading":"What audiences actually notice","paragraphs":["Speakers tend to overestimate how much listeners notice small grammatical errors or an accent. International medical audiences are used to hearing English spoken with many accents, and a large proportion of them are non-native speakers themselves.","What audiences do notice is whether they can follow you: a clear purpose, a logical structure, key terms they can recognise, and a pace that gives them time to think. A speaker with an accent and a clear structure is consistently easier to follow than a fluent speaker without one."]},{"heading":"Separating language accuracy from professional credibility","paragraphs":["Your credibility on stage comes from your expertise, your preparation and the clarity of your message. Language accuracy supports that credibility, but it is not the same thing. Treating every small error as a threat to your authority increases anxiety and makes errors more likely.","Throughout this program you will work on the language features that genuinely affect understanding, and deliberately let go of those that do not. That shift alone often reduces anxiety noticeably."]}],"examples":[{"title":"Two openings, same content","text":"Speaker A apologises for her English, then reads a dense first slide quickly. Speaker B, with a stronger accent, pauses, says “Today I want to show you one finding that changed how we treat post-operative delirium,” and waits a moment. Audiences consistently rate Speaker B as more confident and more expert."},{"title":"The apology trap","text":"“Sorry for my English” invites the audience to listen for mistakes. Replace it with a clear statement of purpose. If language is genuinely a concern, a single sentence such as “Please stop me if anything is unclear” is more confident and more useful."}],"demonstration":"Watch for three things in the lesson video: where the speaker pauses, how the first sentence states a purpose rather than an apology, and how a key term is repeated slowly the first time it appears.","mistakes":["Apologising for your English at the start of a talk","Writing a word-for-word script and reading it under pressure","Correcting small grammar slips aloud, which draws attention to them","Speeding up to reach the end of a sentence before losing the words"],"reflection":["In which speaking situations do you notice the strongest self-monitoring?","Which of your worries is about language accuracy, and which is about being understood?"]}'::jsonb, '{"title":"Map your speaking triggers","instructions":"Think about the last two occasions on which you spoke in English to a professional audience. Describe the situation, the moment you felt most uncomfortable, and what you noticed in your body and your speech.","prompt":"Describe both situations and what happened (at least 150 characters).","min_chars":150}'::jsonb, '{"title":"Your speaking profile","brief":"Write a short speaking profile (150–300 words): your current professional speaking situations, what you would like to do differently in ten weeks, and one specific talk you would like to give with confidence. You will revisit this profile in Module 12.","min_words":150,"required":true}'::jsonb, null, null, null from public.lessons where code = 'L01'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
