insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'Why do many speakers find presenting in a second language more tiring?', array['Because their medical knowledge is weaker in English', 'Because attention is divided between the message and monitoring the language', 'Because international audiences are more critical', 'Because slides are harder to design in English']::text[], 1, 'Second-language speaking adds real-time language monitoring to the task, which increases cognitive load. It is not a sign of weaker knowledge.' from public.lessons where code = 'L01';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'What do international audiences rely on most to follow a talk?', array['A native-like accent', 'Perfect grammar', 'A clear purpose, structure and manageable pace', 'A large number of slides']::text[], 2, 'Audiences need to understand where the talk is going and have time to process it. Clarity and structure matter more than accent.' from public.lessons where code = 'L01';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'Which opening is most likely to build credibility?', array['“Sorry for my English, I will try my best.”', 'Reading the title slide aloud quickly', '“Today I want to show you one finding that changed our practice.”', 'Starting with the methods section']::text[], 2, 'A clear statement of purpose signals confidence and gives the audience a reason to listen.' from public.lessons where code = 'L01';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 4, 'When you make a small grammatical slip during a talk, the best response is usually to:', array['Stop and correct it explicitly', 'Continue with your message', 'Apologise to the audience', 'Repeat the whole sentence']::text[], 1, 'Small slips rarely affect understanding. Correcting them aloud draws attention to them and interrupts your flow.' from public.lessons where code = 'L01';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L01');
