insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"Nervous energy is not the enemy. The same physiological arousal that feels like anxiety can support focus and presence if you prepare for it. This lesson gives you a practical routine for the hour, the minutes and the first thirty seconds before you speak.","objectives":["Recognise the physical signs of performance arousal","Use a breathing and grounding routine before speaking","Prepare and rehearse your first thirty seconds so that they run on their own"],"sections":[{"heading":"Arousal is energy","paragraphs":["A faster heartbeat, dry mouth and restless hands are signs that your body is preparing to perform. Trying to eliminate them completely rarely works and often increases the anxiety. A more useful goal is to bring arousal into a range where it sharpens rather than scatters your attention.","Many speakers find it helpful to label the sensation differently: not “I am nervous” but “my body is getting ready”. The sensation is the same; the interpretation changes how you respond to it."]},{"heading":"A pre-speaking routine","paragraphs":["One hour before: check the room and the technology, then stop editing slides. Ten minutes before: slow breathing with a longer exhale than inhale, for example inhaling for four counts and exhaling for six, repeated for two minutes. One minute before: stand or sit with both feet on the floor, feel the contact, and silently rehearse your first sentence.","A routine works because it is familiar. Practise it before low-stakes situations, such as a ward meeting, so that it is automatic when the stakes are high."]},{"heading":"The first thirty seconds","paragraphs":["The opening is where anxiety peaks and where second-language speakers most often rush. Prepare it word for word, rehearse it aloud until it feels natural, and include a deliberate pause after your first sentence.","Once the first thirty seconds are behind you, most speakers find their rhythm. You are not memorising the whole talk; you are building a reliable on-ramp into it."]}],"examples":[{"title":"A rehearsed opening","text":"“Good morning. [pause] In the next ten minutes I want to show you why we stopped routine catheterisation after hip surgery — and what happened to our infection rates. [pause]”"},{"title":"A grounding cue","text":"One cardiologist places her notes on the lectern, presses both palms flat on it for two seconds, then looks up and begins. The gesture is invisible to the audience but tells her body that it is time to start."}],"demonstration":"The video demonstrates the four-six breathing pattern and a full rehearsed opening, delivered first too quickly and then with deliberate pauses.","mistakes":["Editing slides in the final minutes before speaking","Trying to suppress all signs of nervousness","Improvising the opening sentence","Starting to speak before reaching the lectern or before the room is ready"],"reflection":["Which part of the routine feels most natural to you, and which feels awkward?","Where in your next week could you practise the routine in a low-stakes setting?"]}'::jsonb, '{"title":"Write and rehearse your first thirty seconds","instructions":"Choose a presentation you are likely to give in the coming months. Write its opening (no more than 70 words), mark where you will pause, then rehearse it aloud five times.","prompt":"Paste your opening with pauses marked as [pause].","min_chars":120}'::jsonb, '{"title":"Pre-speaking routine plan","brief":"Describe your personal pre-speaking routine for one hour, ten minutes and one minute before speaking (100–250 words), and name the low-stakes situation in which you will practise it this week.","min_words":100,"required":true}'::jsonb, null, null, null from public.lessons where code = 'L02'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
delete from public.quiz_questions where lesson_id = (select id from public.lessons where code = 'L02');
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'What is a realistic goal for pre-speaking arousal?', array['Eliminate it completely', 'Bring it into a range that sharpens focus', 'Ignore it', 'Increase it with caffeine']::text[], 1, 'Some arousal supports performance; the aim is to regulate it, not remove it.' from public.lessons where code = 'L02';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'Which breathing pattern is recommended in this lesson?', array['Exhale longer than you inhale', 'Inhale longer than you exhale', 'Hold your breath for ten seconds', 'Breathe as fast as possible']::text[], 0, 'A longer exhale, such as four counts in and six counts out, supports a calmer state.' from public.lessons where code = 'L02';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'Why should the opening be rehearsed word for word?', array['So the whole talk can be read', 'Because anxiety peaks at the start and a reliable opening carries you into the talk', 'To avoid eye contact', 'Because audiences remember only the opening']::text[], 1, 'A rehearsed opening reduces load at the moment of highest anxiety.' from public.lessons where code = 'L02';
delete from public.lesson_resources where lesson_id = (select id from public.lessons where code = 'L02');

