insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"Confident speakers rarely try to sound like someone else. They have a clear sense of the kind of speaker they are and want to become. This lesson helps you define your speaker identity and set specific goals for the ten weeks ahead.","objectives":["Describe the strengths you already bring as a medical speaker","Define the professional voice you want to be known for","Set three measurable speaking goals for the program"],"sections":[{"heading":"Strengths you already have","paragraphs":["Medical professionals bring real advantages to the podium: deep subject knowledge, experience explaining difficult information to patients, and the habit of structured reasoning. These are the foundation of authority.","Start by naming them. When you know what you already do well, it is easier to build on it rather than focusing only on what you lack."]},{"heading":"Defining your professional voice","paragraphs":["Think of two or three words you would like an audience to use about you after a talk — for example “clear”, “practical” and “warm”. These words become a compass for decisions about structure, language and delivery.","Your voice should be authentic. A calm, precise speaker does not need to become theatrical to be effective."]},{"heading":"Goals that can be measured","paragraphs":["Vague goals such as “be more confident” are hard to act on. Useful goals describe behaviour you can observe or measure: speaking at a comfortable pace, pausing before key results, or answering three audience questions without notes.","The Speaking Studio will help you measure some of these, such as pace and filler words. Others will be assessed by you and your instructors."]}],"examples":[{"title":"From vague to measurable","text":"“I want to sound more confident” becomes “In my next case presentation I will pause after stating the diagnosis and keep my pace below 160 words per minute.”"},{"title":"Three words","text":"A neurologist chooses “clear, calm, curious”. She decides to open each talk with a question and to slow down whenever she presents data."}],"demonstration":"The video shows two short self-introductions by the same speaker: one generic, one built around three chosen words.","mistakes":["Copying the style of a speaker whose personality is very different from yours","Setting goals that cannot be observed","Setting too many goals at once"],"reflection":["Which three words would you like an audience to use about you?","Which goal would make the biggest difference to your work in the next year?"]}'::jsonb, '{"title":"Three words and three goals","instructions":"Choose the three words that describe the speaker you want to be, and write three specific, observable goals for the next ten weeks.","prompt":"Your three words and three goals.","min_chars":120}'::jsonb, '{"title":"Ten-week development goals","brief":"Write your three goals for the program (100–250 words). For each, explain why it matters in your professional context and how you will know you have achieved it.","min_words":100,"required":true}'::jsonb, null, null, null from public.lessons where code = 'L03'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
