insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 1, 'Which of these is a measurable speaking goal?', array['Be more confident', 'Sound more professional', 'Pause after stating each key result', 'Improve my English']::text[], 2, 'A measurable goal describes behaviour that can be observed or measured.' from public.lessons where code = 'L03';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 2, 'What is the purpose of choosing three words for your professional voice?', array['To memorise them for the talk', 'To guide decisions about structure, language and delivery', 'To put them on your title slide', 'To impress the audience']::text[], 1, 'The words act as a compass for consistent choices.' from public.lessons where code = 'L03';
insert into public.quiz_questions (lesson_id, position, prompt, options, correct_index, explanation) select id, 3, 'Which statement best reflects authentic speaking?', array['Imitate the most famous speaker you know', 'Build on your existing strengths and personality', 'Always be theatrical', 'Avoid showing any personality']::text[], 1, 'Effective speakers develop their own voice rather than copying someone else’s.' from public.lessons where code = 'L03';
