insert into public.lesson_content (lesson_id, body, exercise, assignment, video_url, captions_url, video_note)
  select id, '{"intro":"When speaking under pressure, most presenters speed up. In a second language the effect is stronger: we hurry to reach the end of a sentence before we lose the words. The audience pays the price, because they need time to process technical content. This lesson teaches you to control pace, use pauses deliberately and place emphasis where meaning lives.","objectives":["Measure your natural speaking pace","Place deliberate pauses before and after key messages","Use emphasis to signal what matters"],"sections":[{"heading":"Why pace matters for international audiences","paragraphs":["Listeners process spoken technical information more slowly than written information, and non-native listeners need a little more time again. A pace that feels natural to you in conversation can be too fast for a lecture hall.","As a practical reference, many speakers find that around 130 to 160 words per minute works well for international medical audiences. Treat this as a guide, not a rule: dense data needs a slower pace than a story."]},{"heading":"The deliberate pause","paragraphs":["A pause is not an absence of speech. It is where your audience understands you. Pause before a key result to create attention, and after it to give the audience time to absorb it.","Pauses also give you thinking time. Many fillers — “um”, “uh”, “so” — are simply pauses that have been filled with sound. Allowing a silent pause instead removes the filler and sounds more authoritative."]},{"heading":"Emphasis","paragraphs":["In English, emphasis is carried by stress: the important word in a sentence is slightly louder, longer and higher. “Mortality fell by a THIRD” tells the audience exactly what to remember.","Mark your key words in your notes and rehearse them aloud. Too much emphasis is as unhelpful as none; aim for one stressed idea per sentence."]}],"examples":[{"title":"Before and after","text":"Before: “So um we found that the readmission rate was lower in the intervention group which was quite interesting.” After: “We found that readmissions were lower. [pause] By a THIRD. [pause]”"},{"title":"Pausing around data","text":"When showing a graph, say what the audience should look at, pause while they look, then state the conclusion."}],"demonstration":"The sample video shows how captions and playback speed work in the lesson player. The instructor recording will demonstrate the same talk delivered at three different speeds.","mistakes":["Speeding up when time is short instead of cutting content","Filling every silence with “um” or “so”","Stressing every word, so that nothing stands out","Pausing in the middle of a technical term"],"reflection":["Where in your talks do you tend to speed up?","Which sentence in your next presentation most deserves a pause before it?"]}'::jsonb, '{"title":"Mark your pauses","instructions":"Take the opening you wrote in Lesson 2 (or any 60–100 word passage from a talk). Mark at least three pauses with [pause] and capitalise the one word per sentence that carries the main stress. Then read it aloud twice: once naturally, once following your marks.","prompt":"Paste your marked passage and note one difference you heard between the two readings.","min_chars":150}'::jsonb, '{"title":"Pace reflection","brief":"After practising your marked passage, write a short reflection (80–200 words): what changed when you used deliberate pauses, and where you will use them in your next presentation. In Stage 4 you will be able to record this passage in the Speaking Studio.","min_words":80,"required":true}'::jsonb, '/media/sample/l07-sample.mp4', '/media/sample/l07-sample.vtt', 'Sample video for demonstrating the player. The instructor recording for this lesson has not been produced yet.' from public.lessons where code = 'L07'
  on conflict (lesson_id) do update set body = excluded.body, exercise = excluded.exercise, assignment = excluded.assignment, video_url = excluded.video_url, captions_url = excluded.captions_url, video_note = excluded.video_note;
